"""Phase 2.6: applies the preregistered localization criteria mechanically and writes tables (results/phase26/report_tables.md)."""
import json
from pathlib import Path

import numpy as np

R = Path(__file__).resolve().parents[1] / "results/phase26"
J = json.load(open(R / "position_patching.json"))
md = ["# Phase 2.6 tables (auto-generated by scripts/phase26_report.py)\n"]
ml = md.append
ml(f"Validation: {json.dumps(J['validation'])[:900]}\n")
ml(f"Group checks: {json.dumps(J['group_checks'])}\nRandom-control flags: {json.dumps(J['random'])}\n")
verdict = {}
for fmt, o in J["formats"].items():
    ml(f"\n## {fmt}  (trials {o['n_trials']}, clean trials {o['n_clean']}, source-target margin gap {o['gap']:.1f}, self-patch noise floor max {o['noise_floor_max_abs']} logits)\n")
    for qs, label in (("last", "PRIMARY: last query row"), ("all", "secondary: all query rows")):
        s = o["sets"][f"S8|{qs}"]; c = s["conditions"]
        ml(f"\n### S8 jointly — {label}; T(All) = {s['T_all']:.3f} [95 % CI {s['T_all_ci'][0]:.3f}, {s['T_all_ci'][1]:.3f}], evaluable: {s['evaluable']}\n")
        ml("| condition | T (margin transfer) [95 % CI] | F = T/T(All) [95 % CI] | verdict-coordinate transfer | direct head-output transfer | flip to source (clean) |\n|---|---|---|---|---|---|")
        for k in ["G1", "G2", "G1G2", "Rem", "Self", "RemExSelf", "All"]:
            r = c[k]; ml(f"| {k} | {r['T']:+.3f} [{r['T_ci'][0]:+.3f}, {r['T_ci'][1]:+.3f}] | {('%.3f' % r['F']) if r['F'] is not None else 'undefined'} " + (f"[{r['F_ci'][0]:.3f}, {r['F_ci'][1]:.3f}]" if r['F_ci'] else "") + f" | {r['coord_T']:+.3f} | {r['direct_T']:+.3f} | {r['flip']:.3f} |")
        ml("\nCount-matched random source positions (10 draws each, pool = Remaining excluding Self): " + "; ".join(f"matched to {m}: mean F {v['F_mean']:.4f}, max F {v['F_max']:.4f}, mean T {v['T_mean']:+.4f}" for m, v in s["random"].items() if v and v["F_mean"] is not None))
        i = s["interactions"]
        ml(f"\nInteractions (T-scale): T(G1∪G2) − T(G1) − T(G2) = {i['G1G2_minus_G1_minus_G2']:+.3f} [{i['ci1'][0]:+.3f}, {i['ci1'][1]:+.3f}]; T(All) − T(G1∪G2) − T(Remaining) = {i['All_minus_G1G2_minus_Rem']:+.3f} [{i['ci2'][0]:+.3f}, {i['ci2'][1]:+.3f}]")
    ml("\n### Individual heads (primary query setting): F(G1∪G2) / F(Remaining) / T(All)   [G1, G2 where run]\n\n| head | T(All) | F(G1∪G2) | F(Remaining) | F(G1) | F(G2) | T(G1∪G2) | note |\n|---|---|---|---|---|---|---|---|")
    for hname in ("L22H5", "L21H19", "L20H8", "L22H8", "L22H15", "L19H10", "L22H6", "L22H4"):
        s = o["sets"][f"{hname}|last"]; c = s["conditions"]; f = lambda k: ("%.2f" % c[k]["F"]) if k in c and c[k]["F"] is not None else "n/a"
        ml(f"| {hname} | {s['T_all']:+.3f} | {f('G1G2')} | {f('Rem')} | {f('G1')} | {f('G2')} | {c['G1G2']['T']:+.3f} | {'not evaluable (T(All) < 0.20)' if not s['evaluable'] else ''} |")
    # preregistered rule on S8, primary
    s = o["sets"]["S8|last"]; c = s["conditions"]
    ok = dict(F_G1G2=c["G1G2"]["F"] if c["G1G2"]["F"] is not None else float("nan"), F_Rem=c["Rem"]["F"] if c["Rem"]["F"] is not None else float("nan"),
              rand_mean=s["random"]["G1G2"]["F_mean"], rand_max=s["random"]["G1G2"]["F_max"])
    ok["supported"] = bool(s["evaluable"] and ok["F_G1G2"] >= 0.70 and ok["F_Rem"] <= 0.20 and ok["rand_mean"] <= 0.15 and ok["rand_max"] <= 0.30)
    ok["partial"] = bool(s["evaluable"] and not ok["supported"] and ok["F_G1G2"] >= 0.40)
    verdict[fmt] = ok
lex = J.get("lexical_controls", {})
if "results" in lex:
    ml(f"\n## Same-label lexical controls (S8, aligned same-label pairs with different content; n = {lex['n_trials']}, rejected {lex['rejected']})\n\n| condition | verdict-change rate | mean |Δ margin| | max |Δ margin| |\n|---|---|---|---|")
    for k, v in lex["results"].items(): ml(f"| {k} | {v['verdict_change']:.3f} | {v['mean_abs_margin_change']:.2f} | {v['max_abs_margin_change']:.2f} |")
both = all(v["supported"] for v in verdict.values()) and len(verdict) == 2
overall = "LOCALIZATION SUPPORTED (both formats)" if both else ("PARTIALLY LOCALIZED / mixed across formats" if any(v["supported"] or v["partial"] for v in verdict.values()) else "NOT LOCALIZED")
ml(f"\n## Preregistered criteria (S8, last query row)\n```json\n{json.dumps(verdict, indent=1)}\n```\n**Overall: {overall}.**")
(R / "report_tables.md").write_text("\n".join(md)); json.dump(dict(per_format=verdict, overall=overall), open(R / "criteria_verdict.json", "w"), indent=1)
print("\n".join(md))
